// Generated by create-agent-starter — safe to edit.
// Worker HTTP entry: auth-guarded agent routes, approvals, tenant sync, eval harness, module routes.
import "@agent-starter/flue/cloudflare";
import { createTenantSyncRoutes } from "@agent-starter/cloudflare";
import { agentAuth, createApprovalRoutes, createConversationRoute, installAgentStarterObserver, registerExtendedModels } from "@agent-starter/flue";
import { createAgentRouter } from "@flue/runtime/routing";
import { type Context, Hono } from "hono";
import type { Env } from "./env.ts";
import { agentCors } from "./lib/cors.ts";
import { evalHarness } from "./lib/evals.ts";
import { artifactRoutes, chatRateLimiter, classifyDelivery, integrationRoutes, modelGateway, observerOptions, pusherAuthRoutes, seedInitialData, tenantConfigs } from "./lib/platform.ts";
import { APPROVAL_DECIDER_ROLES, OPERATOR_ROLES } from "./lib/access.ts";
import { signingSecret } from "./lib/policy.ts";
import { Assistant } from "./agents/assistant.ts";
import { Copilot } from "./agents/copilot.ts";
import { BackgroundWorker } from "./agents/background-worker.ts";
import { Orchestrator } from "./agents/orchestrator.ts";
import { AnalystAgent, ContentProducerAgent, DistributionManagerAgent, MediaBuyerAgent, SecurityAuditorAgent, SeoEditorAgent, StrategistAgent, WriterAgent } from "./agents/specialists.ts";
import { PersistentAgent } from "./agents/persistent.ts";
import { oauthMcpRoutes } from "./in-app/oauth-mcp.ts";
import { backgroundRoutes } from "./background/routes.ts";
import { roomRoutes } from "./multi-agent/routes.ts";
import { persistentRoutes } from "./persistent/routes.ts";
import { appContextFromRequest } from "./lib/app-context.ts";

// Adds GPT-6.1 Terra (default frontier model) to Flue's OpenAI catalog, routed through Cloudflare AI Gateway
// when CF_ACCOUNT_ID + AI_GATEWAY_ID are set, then wires telemetry + run registry. Keep both at module top level.
registerExtendedModels(modelGateway());
installAgentStarterObserver(observerOptions());

const sessionSecrets = (c: Context) => [c.env.SESSION_SIGNING_SECRET, c.env.SESSION_SIGNING_SECRET_PREVIOUS].filter(Boolean) as string[];
// Cookie-authenticated POSTs must come from the agent's own origin or one of these (CSRF); bearer tokens are unaffected.
const trustedOrigins = (c: Context) => (c.env.ALLOWED_ORIGINS ?? "").split(",").map((o: string) => o.trim()).filter(Boolean);
// Chat turns are rate limited per tenant; TenantConfig.rateLimit overrides chatRateLimiter's defaults.
const tenantRateLimit = (_c: Context, tenantId: string) => tenantConfigs().get(tenantId);
// Edge routing: classifyDelivery (src/lib/platform.ts, the Workers AI utility model) labels each signal / voice
// delivery SIMPLE (first-line model) or COMPLEX (frontier); agentAuth stamps the verdict as a server-trusted
// `route` attribute the agent reads.
const WIDGET_PATHS: string[] = [];

const app = new Hono<{ Bindings: Env }>();

app.get("/health", (c) => c.json({ ok: true, service: c.env.SERVICE_NAME, version: c.env.CODE_VERSION }));

// CORS: ALLOWED_ORIGINS on every route WITH credentials; registered widget sites on widget routes only, without.
app.use("*", agentCors(WIDGET_PATHS));

app.use("/agents/assistant/*", agentAuth({ secret: sessionSecrets, agentName: "assistant", mount: "/agents/assistant", rateLimiter: chatRateLimiter, tenantConfig: tenantRateLimit, classify: classifyDelivery, trustedOrigins, extraInitialData: (_c, claims) => seedInitialData(claims) }));
app.route("/agents/assistant", createAgentRouter(Assistant));
app.route("/api/assistant", createConversationRoute({ agentName: "assistant", secret: sessionSecrets }));

app.use("/agents/copilot/*", agentAuth({ secret: sessionSecrets, agentName: "copilot", mount: "/agents/copilot", rateLimiter: chatRateLimiter, tenantConfig: tenantRateLimit, classify: classifyDelivery, trustedOrigins, extraInitialData: async (c, claims) => ({ ...(await seedInitialData(claims)), ...appContextFromRequest(c) }) }));
app.route("/agents/copilot", createAgentRouter(Copilot));
app.route("/api/copilot", createConversationRoute({ agentName: "copilot", secret: sessionSecrets }));

app.use("/agents/background-worker/*", agentAuth({ secret: sessionSecrets, agentName: "background-worker", mount: "/agents/background-worker", adminRoles: [...OPERATOR_ROLES], rateLimiter: chatRateLimiter, tenantConfig: tenantRateLimit, classify: classifyDelivery, trustedOrigins, extraInitialData: (_c, claims) => seedInitialData(claims) }));
app.route("/agents/background-worker", createAgentRouter(BackgroundWorker));
app.route("/api/background-worker", createConversationRoute({ agentName: "background-worker", secret: sessionSecrets }));

app.use("/agents/orchestrator/*", agentAuth({ secret: sessionSecrets, agentName: "orchestrator", mount: "/agents/orchestrator", rateLimiter: chatRateLimiter, tenantConfig: tenantRateLimit, classify: classifyDelivery, trustedOrigins, extraInitialData: (_c, claims) => seedInitialData(claims) }));
app.route("/agents/orchestrator", createAgentRouter(Orchestrator));
app.route("/api/orchestrator", createConversationRoute({ agentName: "orchestrator", secret: sessionSecrets }));

// Decisions are attributed to the signed-in user (session), never a header; recipient-bound links require that session.
// Decide-by-id (POST /approvals/by-id/:conversationId/:approvalId) is open to the roles that grant agent:approve in the
// catalog (owner, admin, marketer: docs/auth/permissions.json), in the conversation's own tenant.
app.route("/", createApprovalRoutes({ operatorRoles: APPROVAL_DECIDER_ROLES, agents: [Assistant, Copilot, BackgroundWorker, Orchestrator, StrategistAgent, ContentProducerAgent, SeoEditorAgent, MediaBuyerAgent, DistributionManagerAgent, AnalystAgent, WriterAgent, SecurityAuditorAgent, PersistentAgent], secret: (c) => c.env.APPROVAL_SIGNING_SECRET, sessionSecret: sessionSecrets, appName: "Marketer" }));
app.route("/", createTenantSyncRoutes<Env>({ kv: (env) => env.TENANT_CONFIG, secret: (env) => signingSecret(env, "tenantSync") ?? "" }));
// Composio account connections (signed-in users; active when integrations.composio is on in agent-starter.config.ts).
app.route("/", integrationRoutes);
// Signed, expiring artifact downloads (links in job results): GET /artifacts/:tenantId/*.
app.route("/", artifactRoutes);
// Pusher private-channel auth for live dashboards (404 until PUSHER_* are set and integrations.pusher is on).
app.route("/", pusherAuthRoutes);
app.post("/api/test-eval-harness", (c) => evalHarness(c.req.raw, c.env));
app.route("/", oauthMcpRoutes);
app.route("/", backgroundRoutes);
app.route("/", roomRoutes);
app.route("/", persistentRoutes);

export default app;
